/**
 * ParsedDocument
 *
 * Provider-neutral parsed document.
 *
 * Mapping policy:
 * - `raw`: original provider JSON or response payload for debugging/replay.
 * - `html`: document-level HTML when a parser provides it.
 * - `markdown`: document-level Markdown when a parser provides it.
 * - `text`: plain text or low-fidelity raw text fallback.
 * - `elements`: canonical structured representation used by chunking.
 */
export type ParsedDocument = {
    /**
     * Schema Version
     */
    schema_version?: string;
    /**
     * Doc Id
     */
    doc_id: string;
    /**
     * Source
     */
    source?: string | null;
    /**
     * Filename
     */
    filename?: string | null;
    /**
     * Mimetype
     */
    mimetype?: string | null;
    /**
     * Parser
     */
    parser: string;
    /**
     * Pages
     */
    pages?: Array<ParsedPage>;
    /**
     * Elements
     */
    elements?: Array<ParsedElement>;
    /**
     * Text
     */
    text?: string;
    /**
     * Html
     */
    html?: string;
    /**
     * Markdown
     */
    markdown?: string;
    /**
     * Metadata
     */
    metadata?: {
        [key: string]: unknown;
    };
    /**
     * Raw
     */
    raw?: {
        [key: string]: unknown;
    };
};

/**
 * ParsedElement
 *
 * Smallest parser-normalized unit consumed by chunking.
 *
 * `content` should hold the canonical representation described by `format`.
 * Examples: headings and paragraphs as Markdown/text, tables as raw
 * `<table>...</table>` HTML, equations as LaTeX, and images as `asset_ref`
 * plus optional OCR/caption metadata.
 */
export type ParsedElement = {
    /**
     * Element Id
     */
    element_id: string;
    type: ElementType;
    format: ContentFormat;
    /**
     * Content
     */
    content?: string;
    /**
     * Page Id
     */
    page_id?: string | null;
    /**
     * Order
     */
    order: number;
    /**
     * Level
     *
     * Heading/list nesting level when available.
     */
    level?: number | null;
    bbox?: BoundingBox | null;
    /**
     * Provenance
     */
    provenance?: Array<Provenance>;
    /**
     * Parent Id
     */
    parent_id?: string | null;
    /**
     * Children Ids
     */
    children_ids?: Array<string>;
    asset?: AssetRef | null;
    /**
     * Ignored
     *
     * Whether this element is layout boilerplate and ignored during chunking.
     */
    ignored?: boolean;
    /**
     * Metadata
     */
    metadata?: {
        [key: string]: unknown;
    };
};

/**
 * ParsedPage
 *
 * Physical or rendered page metadata.
 *
 * `page_id` is the join key used by text chunks, page images, and vision
 * indexes. For web or text-only sources, adapters may emit one synthetic page.
 */
export type ParsedPage = {
    /**
     * Page Id
     */
    page_id: string;
    /**
     * Page No
     */
    page_no: number;
    /**
     * Width
     */
    width?: number | null;
    /**
     * Height
     */
    height?: number | null;
    image?: AssetRef | null;
    /**
     * Metadata
     */
    metadata?: {
        [key: string]: unknown;
    };
};

/**
 * Provenance
 *
 * Trace information linking an IR element back to provider output.
 */
export type Provenance = {
    /**
     * Page No
     */
    page_no?: number | null;
    bbox?: BoundingBox | null;
    /**
     * Charspan
     */
    charspan?: [
        number,
        number
    ] | null;
    /**
     * Source Ref
     *
     * Provider-specific source reference such as #/texts/0.
     */
    source_ref?: string | null;
    /**
     * Metadata
     */
    metadata?: {
        [key: string]: unknown;
    };
};

/**
 * ProviderOptions
 */
export type ProviderOptions = {
    /**
     * Embedding Models
     *
     * List of available embedding models
     */
    embedding_models: Array<string>;
    /**
     * Llm Models
     *
     * List of available LLM models
     */
    llm_models: Array<string>;
    /**
     * Reranker Models
     *
     * List of available reranker models
     */
    reranker_models: Array<string>;
    /**
     * Parser Providers
     *
     * List of available parser providers
     */
    parser_providers: Array<string>;
};

